// <auto-generated/>
// Round-trip serialization tests for Nalix TypeScript packets

import { test } from 'node:test';
import assert from 'node:assert/strict';
import * as P from '../src/packets.js';

test('Control round-trip binary serialization', () => {
  const pkt = new P.Control();
  pkt.header.opcode = P.Control.OPCODE;
  pkt.header.sequenceId = 42;
  pkt.reason = 42;
  pkt.type = 42;
  const encoded = pkt.encode();
  assert.ok(encoded.byteLength >= P.Control.FIXED_SIZE);
  const decoded = P.Control.decode(encoded);
  assert.equal(decoded.header.opcode, P.Control.OPCODE);
  assert.equal(decoded.header.sequenceId, 42);
  assert.equal(decoded.reason, pkt.reason);
  assert.equal(decoded.type, pkt.type);
});

