test('ProofOfWorkChallenge round-trip binary serialization', () => {
  const pkt = new P.ProofOfWorkChallenge();
  pkt.header.opcode = P.ProofOfWorkChallenge.OPCODE;
  pkt.header.sequenceId = 42;
  pkt.nonce.fill(0x5a);
  pkt.difficulty = 42;
  pkt.timestampTicks = 123456789012345678n;
  pkt.mac.fill(0x5a);
  const encoded = pkt.encode();
  assert.ok(encoded.byteLength >= P.ProofOfWorkChallenge.FIXED_SIZE);
  const decoded = P.ProofOfWorkChallenge.decode(encoded);
  assert.equal(decoded.header.opcode, P.ProofOfWorkChallenge.OPCODE);
  assert.equal(decoded.header.sequenceId, 42);
  assert.deepEqual(decoded.nonce, pkt.nonce);
  assert.equal(decoded.difficulty, pkt.difficulty);
  assert.equal(decoded.timestampTicks, pkt.timestampTicks);
  assert.deepEqual(decoded.mac, pkt.mac);
});

